<?php
require_once __DIR__.'/../includes/functions.php';require_role('admin');verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){try{db()->prepare('INSERT INTO teacher_subjects(teacher_id,subject_id,class_id) VALUES(?,?,?)')->execute([(int)$_POST['teacher_id'],(int)$_POST['subject_id'],(int)$_POST['class_id']]);audit('Assigned teacher to subject/class');flash('success','Teacher assignment saved.');}catch(Throwable $e){flash('danger','Could not save assignment (it may already exist).');}redirect('assignments.php');}
$teachers=db()->query("SELECT t.teacher_id,u.name FROM teachers t JOIN users u ON u.user_id=t.user_id WHERE u.status='active'")->fetchAll();$subjects=db()->query('SELECT * FROM subjects')->fetchAll();$classes=db()->query('SELECT * FROM classes')->fetchAll();$rows=db()->query('SELECT ts.assignment_id,u.name,s.subject_name,c.class_name FROM teacher_subjects ts JOIN teachers t ON t.teacher_id=ts.teacher_id JOIN users u ON u.user_id=t.user_id JOIN subjects s ON s.subject_id=ts.subject_id JOIN classes c ON c.class_id=ts.class_id')->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="row g-3"><div class="col-md-4"><div class="card"><div class="card-header">New assignment</div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-2"><label class="form-label">Teacher</label><select class="form-select" name="teacher_id" required><?php foreach($teachers as $t):?><option value="<?=$t['teacher_id']?>"><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="mb-2"><label class="form-label">Subject</label><select class="form-select" name="subject_id" required><?php foreach($subjects as $s):?><option value="<?=$s['subject_id']?>"><?=e($s['subject_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Class</label><select class="form-select" name="class_id" required><?php foreach($classes as $c):?><option value="<?=$c['class_id']?>"><?=e($c['class_name'].' · '.$c['department'].' · Sem '.$c['semester'])?></option><?php endforeach;?></select></div><button class="btn btn-primary">Assign</button></form></div></div></div><div class="col-md-8"><div class="card"><div class="card-header">Current assignments</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Teacher</th><th>Subject</th><th>Class</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['class_name'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php include __DIR__.'/../includes/footer.php';?>